local a="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local d=[=[]=]
local out={}
local buffer=0
local bits=0
for i=1,#d do
 local c=d:sub(i,i)
 if c~="=" then
  local v=a:find(c,1,true)-1
  buffer=buffer*64+v
  bits=bits+6
  if bits>=8 then
   bits=bits-8
   out[#out+1]=string.char(math.floor(buffer/2^bits)%256)
   buffer=buffer%2^bits
  end
 end
end
assert(loadstring(table.concat(out)))()